/* Arefi ITPraxis – Vertiefung Lernstrecke Windows Server 2025, Module 7–12 (DNS/DHCP, Verwaltung, Dateidienste, PKI, Hyper-V, IIS). [fa, de, en] */
(() => {
'use strict';
const R = String.raw;
window.ArefiPlus(window.ArefiWSCourse, {

'ws-dnsdhcp': {
  know: [
    ['پاک‌سازی رکوردهای کهنه (Scavenging) دو بخش دارد: Aging روی Zone و Scavenging روی سرور؛ هر دو باید فعال باشند. بدون آن رکوردهای قدیمی می‌مانند و نام‌ها به IP اشتباه می‌روند.', 'Aufräumen veralteter Einträge (Scavenging) hat zwei Teile: Aging an der Zone und Scavenging am Server – beide müssen aktiv sein. Sonst bleiben alte Einträge und Namen zeigen auf falsche IPs.', 'Cleaning up stale records (scavenging) has two parts: aging on the zone and scavenging on the server – both must be enabled. Otherwise old records remain and names point to wrong IPs.'],
    ['Conditional Forwarder فقط درخواست‌های یک دامنهٔ مشخص (مثلاً شرکت همکار یا یک Private DNS در Azure) را به سرور معینی می‌فرستد؛ بقیه از Forwarder عمومی می‌روند.', 'Eine bedingte Weiterleitung schickt nur Anfragen für eine bestimmte Domäne (etwa einen Partner oder ein privates DNS in Azure) an einen festgelegten Server; alles andere geht über die normale Weiterleitung.', 'A conditional forwarder sends only queries for a specific domain (e.g. a partner or a private DNS zone in Azure) to a given server; everything else uses the normal forwarder.'],
    ['اگر کلاینت در VLAN دیگری از سرور DHCP است، روتر یا سوئیچ لایه ۳ باید درخواست را با DHCP Relay (در Cisco: ip helper-address) به سرور برساند. سرور DHCP ویندوز باید در AD مجاز (Authorize) شده باشد.', 'Steht der Client in einem anderen VLAN als der DHCP-Server, muss Router oder Layer-3-Switch die Anfrage per DHCP-Relay (bei Cisco: ip helper-address) weiterreichen. Ein Windows-DHCP-Server muss in AD autorisiert sein.', 'If the client is in a different VLAN from the DHCP server, the router or layer 3 switch must forward the request via DHCP relay (Cisco: ip helper-address). A Windows DHCP server must be authorized in AD.']
  ],
  code: R`# Vertiefung: DNS- und DHCP-Fehlersuche
Resolve-DnsName intranet.corp.example.test -Server 10.20.0.10
Resolve-DnsName 10.20.0.30 -Type PTR
Resolve-DnsName www.microsoft.com -Server 10.20.0.10   # Weiterleitung ins Internet ok?
Get-DnsServerForwarder
Clear-DnsServerCache -Force
# Aufräumen alter Einträge aktivieren (DC01):
Set-DnsServerZoneAging -Name corp.example.test -Aging $true
Set-DnsServerScavenging -ScavengingState $true -ScavengingInterval 7.00:00:00 -ApplyOnAllZones
Add-DnsServerConditionalForwarderZone -Name partner.example -MasterServers 192.0.2.53 -ReplicationScope Forest
# DHCP (SRV01): Auslastung, Autorisierung, Protokoll
Get-DhcpServerInDC
Get-DhcpServerv4ScopeStatistics | Format-Table ScopeId,Free,InUse,PercentageInUse
Get-DhcpServerv4Lease -ScopeId 10.20.0.0 | Where-Object AddressState -like '*Declined*'
Get-ChildItem C:\Windows\System32\dhcp\DhcpSrvLog-*.log | Sort-Object LastWriteTime | Select-Object -Last 1 | Get-Content -Tail 20`,
  trouble: [
    [['کلاینت‌های فقط یک VLAN آدرس 169.254.x.x می‌گیرند.', 'Nur Clients eines VLANs bekommen 169.254.x.x.', 'Only clients in one VLAN get 169.254.x.x.'],
     ['وقتی بقیهٔ VLANها سالم‌اند، سرور DHCP احتمالاً سالم است. روی روتر یا سوئیچ آن VLAN تنظیم DHCP Relay را بررسی کن (ip helper-address به IP سرور DHCP). Scope همان شبکه باید وجود داشته باشد و فعال باشد؛ با Get-DhcpServerv4Scope وضعیت Active را ببین.', 'Funktionieren die anderen VLANs, ist der DHCP-Server vermutlich in Ordnung. Am Router oder Switch dieses VLANs das DHCP-Relay prüfen (ip helper-address auf die IP des DHCP-Servers). Der Bereich für dieses Netz muss existieren und aktiv sein – Get-DhcpServerv4Scope zeigt State Active.', 'If other VLANs work, the DHCP server is probably fine. Check the DHCP relay on that VLAN’s router or switch (ip helper-address pointing to the DHCP server IP). The scope for that network must exist and be active – Get-DhcpServerv4Scope shows State Active.']],
    [['دستگاه‌های تازه آدرس نمی‌گیرند؛ در لاگ DHCP آمده «Scope پر است».', 'Neue Geräte bekommen keine Adresse; im DHCP-Protokoll steht „Bereich voll“.', 'New devices get no address; the DHCP log says “scope full”.'],
     ['Get-DhcpServerv4ScopeStatistics درصد اشغال را نشان می‌دهد. برای شبکهٔ مهمان مدت Lease را کوتاه کن (مثلاً ۸ ساعت)، Leaseها و رزروهای قدیمی را پاک کن و آدرس‌های Declined (ناشی از تداخل IP) را بررسی کن. اگر شبکه واقعاً کوچک است، با تیم شبکه Subnet بزرگ‌تر برنامه‌ریزی کن.', 'Get-DhcpServerv4ScopeStatistics zeigt die Auslastung. Für Gastnetze die Leasedauer verkürzen (z. B. 8 Stunden), alte Leases und Reservierungen entfernen und abgelehnte Adressen (Declined, durch IP-Konflikte) prüfen. Ist das Netz wirklich zu klein, mit dem Netzwerkteam ein größeres Subnetz planen.', 'Get-DhcpServerv4ScopeStatistics shows utilization. Shorten the lease for guest networks (e.g. 8 hours), remove old leases and reservations and check declined addresses (caused by IP conflicts). If the network really is too small, plan a larger subnet with the network team.']],
    [['نام‌های داخلی کار می‌کنند، سایت‌های اینترنتی نه.', 'Interne Namen gehen, Internetseiten nicht.', 'Internal names work, internet sites do not.'],
     ['کلاینت‌ها درست به DNS داخلی می‌روند؛ اشکال در مسیر DNS به بیرون است. Resolve-DnsName www.microsoft.com -Server 10.20.0.10 را بزن؛ Forwarderها را با Get-DnsServerForwarder ببین و دسترسی‌شان را (UDP و TCP 53 در فایروال خروجی) آزمایش کن. بعد Clear-DnsServerCache. هرگز DNS اینترنتی را مستقیم روی کلاینت دامنه نگذار.', 'Die Clients fragen korrekt den internen DNS; das Problem liegt auf dem Weg nach außen. Resolve-DnsName www.microsoft.com -Server 10.20.0.10 ausführen, Weiterleitungen mit Get-DnsServerForwarder ansehen und deren Erreichbarkeit testen (UDP und TCP 53 in der ausgehenden Firewall). Danach Clear-DnsServerCache. Nie einen Internet-DNS direkt am Domänenclient eintragen.', 'Clients correctly query the internal DNS; the problem is on the way out. Run Resolve-DnsName www.microsoft.com -Server 10.20.0.10, check forwarders with Get-DnsServerForwarder and test their reachability (UDP and TCP 53 in the outbound firewall). Then Clear-DnsServerCache. Never set an internet DNS directly on a domain client.']],
    [['یک نام چند IP برمی‌گرداند که برخی مال دستگاه‌های قدیمی‌اند.', 'Ein Name zeigt mehrere IPs, darunter alte Geräte.', 'A name returns several IPs, including old devices.'],
     ['Scavenging خاموش است یا رکوردها ثابت (Static) ساخته شده‌اند. Aging و Scavenging را فعال کن، رکوردهای اشتباه را دستی حذف کن و برای کامپیوترهای DHCP اجازه بده خود DHCP رکورد را ثبت و پاک کند (DNS Dynamic Updates در تنظیمات DHCP).', 'Scavenging ist aus oder die Einträge wurden statisch angelegt. Aging und Scavenging aktivieren, falsche Einträge von Hand löschen und bei DHCP-Clients den DHCP-Server die Einträge registrieren und entfernen lassen (DNS-dynamische Updates in den DHCP-Einstellungen).', 'Scavenging is off or the records were created as static. Enable aging and scavenging, delete wrong records manually and let the DHCP server register and remove records for DHCP clients (DNS dynamic updates in the DHCP settings).']]
  ],
  decide: [
    [['Forwarder، Conditional Forwarder یا Secondary Zone؟', 'Weiterleitung, bedingte Weiterleitung oder sekundäre Zone?', 'Forwarder, conditional forwarder or secondary zone?'],
     ['Forwarder برای همهٔ اینترنت. Conditional Forwarder برای یک دامنهٔ مشخص که سرور DNS دیگری دارد (همکار، Azure). Secondary Zone وقتی یک نسخهٔ کامل و محلی از آن Zone لازم داری، مثلاً در شعبه بدون DC.', 'Weiterleitung für das gesamte Internet. Bedingte Weiterleitung für eine bestimmte Domäne mit eigenem DNS-Server (Partner, Azure). Sekundäre Zone, wenn eine vollständige lokale Kopie der Zone nötig ist, etwa in einer Außenstelle ohne DC.', 'Forwarder for the whole internet. Conditional forwarder for a specific domain with its own DNS server (partner, Azure). Secondary zone when you need a complete local copy of the zone, e.g. in a branch without a DC.']],
    [['حالت DHCP Failover: Load Balance یا Hot Standby؟', 'DHCP-Failover: Lastenausgleich oder Hot Standby?', 'DHCP failover: load balance or hot standby?'],
     ['Load Balance برای دو سرور هم‌ارز در یک محل (پیش‌فرض ۵۰٪/۵۰٪). Hot Standby وقتی سرور اصلی در شعبه است و سرور مرکزی فقط پشتیبان باشد؛ سرور پشتیبان درصد کوچکی از آدرس‌ها را رزرو نگه می‌دارد.', 'Lastenausgleich für zwei gleichwertige Server am selben Standort (Standard 50/50). Hot Standby, wenn der Hauptserver in der Außenstelle steht und ein zentraler Server nur Reserve ist; der Reserveserver hält einen kleinen Anteil der Adressen zurück.', 'Load balance for two equal servers at the same site (default 50/50). Hot standby when the primary server is in the branch and a central server is only the backup; the backup keeps a small share of addresses in reserve.']]
  ],
  iv: [
    [['کاربری می‌گوید «اینترنت ندارم». با کدام آزمایش‌ها DNS را از شبکه جدا می‌کنی؟', 'Ein Benutzer sagt „kein Internet“. Mit welchen Tests trennst du DNS vom Netzwerk?', 'A user says “no internet”. Which tests separate DNS from the network?'],
     ['ipconfig /all برای IP، Gateway و DNS؛ ping به Gateway؛ Test-NetConnection 1.1.1.1 -Port 443 برای اتصال بدون DNS؛ بعد Resolve-DnsName www.microsoft.com. اگر IP کار می‌کند ولی نام نه، مشکل DNS است؛ اگر هیچ‌کدام کار نمی‌کند، شبکه یا Gateway.', 'ipconfig /all für IP, Gateway und DNS; Ping zum Gateway; Test-NetConnection 1.1.1.1 -Port 443 für Verbindung ohne DNS; dann Resolve-DnsName www.microsoft.com. Geht die IP, aber nicht der Name, ist es DNS; geht beides nicht, Netz oder Gateway.', 'ipconfig /all for IP, gateway and DNS; ping the gateway; Test-NetConnection 1.1.1.1 -Port 443 for connectivity without DNS; then Resolve-DnsName www.microsoft.com. If the IP works but not the name, it is DNS; if neither works, network or gateway.']]
  ]
},

'ws-manage': {
  know: [
    ['PowerShell Remoting روی پورت 5985 (HTTP) و 5986 (HTTPS) کار می‌کند و در دامنه با Kerberos احراز هویت می‌کند. با IP به‌جای نام، Kerberos کار نمی‌کند و تنظیم TrustedHosts یا HTTPS لازم است؛ بهتر است همیشه نام کامل را بنویسی.', 'PowerShell-Remoting läuft über Port 5985 (HTTP) und 5986 (HTTPS) und authentifiziert in der Domäne per Kerberos. Mit IP statt Name geht Kerberos nicht, dann sind TrustedHosts oder HTTPS nötig – besser immer den vollständigen Namen verwenden.', 'PowerShell remoting uses port 5985 (HTTP) and 5986 (HTTPS) and authenticates with Kerberos in the domain. With an IP instead of a name Kerberos fails and TrustedHosts or HTTPS is needed – better always use the full name.'],
    ['مشکل Double Hop: داخل یک نشست راه دور، دسترسی به سرور سوم (مثلاً یک اشتراک) رد می‌شود چون اعتبارنامه منتقل نمی‌شود. فرمان را مستقیم روی سرور مقصد اجرا کن یا فایل را با Copy-Item -ToSession بفرست؛ CredSSP را به‌طور کلی فعال نکن.', 'Double-Hop-Problem: In einer Remotesitzung scheitert der Zugriff auf einen dritten Server (etwa eine Freigabe), weil die Anmeldedaten nicht weitergegeben werden. Den Befehl direkt auf dem Zielserver ausführen oder Dateien per Copy-Item -ToSession übertragen; CredSSP nicht pauschal aktivieren.', 'Double-hop problem: inside a remote session, access to a third server (e.g. a share) is denied because credentials are not passed on. Run the command directly on the target server or send files with Copy-Item -ToSession; do not enable CredSSP broadly.'],
    ['Invoke-Command با چند نام کامپیوتر به‌صورت موازی اجرا می‌شود و خروجی هر سرور با ویژگی PSComputerName برمی‌گردد؛ این پایهٔ گزارش‌های روزانه روی ده‌ها سرور است.', 'Invoke-Command mit mehreren Computernamen läuft parallel und liefert die Ausgabe jedes Servers mit der Eigenschaft PSComputerName zurück – die Grundlage für tägliche Berichte über Dutzende Server.', 'Invoke-Command with several computer names runs in parallel and returns each server’s output with the PSComputerName property – the basis for daily reports across dozens of servers.']
  ],
  code: R`# Vertiefung: viele Server auf einmal prüfen und Remoting-Fehler eingrenzen
Test-WSMan srv01.corp.example.test
Test-NetConnection srv01.corp.example.test -Port 5985
$servers = 'dc01','dc02','srv01'
Invoke-Command -ComputerName $servers -ScriptBlock {
  $os = Get-CimInstance Win32_OperatingSystem
  [pscustomobject]@{
    Name        = $env:COMPUTERNAME
    Laufzeit    = (Get-Date) - $os.LastBootUpTime
    FreiC_GB    = [math]::Round((Get-PSDrive C).Free / 1GB, 1)
    AutoGestopp = (Get-CimInstance Win32_Service -Filter "StartMode='Auto' AND State<>'Running'").Name -join ', '
  }
} | Format-Table Name,Laufzeit,FreiC_GB,AutoGestopp -AutoSize
# auf dem Zielserver, falls Remoting nicht geht:
Get-Service WinRM
winrm enumerate winrm/config/listener
Get-NetFirewallRule -DisplayGroup 'Windows Remote Management' | Format-Table DisplayName,Enabled,Profile`,
  trouble: [
    [['Enter-PSSession پیام «WinRM cannot complete the operation» می‌دهد.', 'Enter-PSSession meldet „WinRM cannot complete the operation“.', 'Enter-PSSession reports “WinRM cannot complete the operation”.'],
     ['ترتیب: نام در DNS درست ترجمه می‌شود؟ Test-NetConnection روی پورت 5985؟ روی سرور مقصد سرویس WinRM روشن است و Listener دارد (winrm enumerate winrm/config/listener)؟ قانون فایروال «Windows Remote Management» برای پروفایل Domain فعال است؟ اگر نه، روی مقصد Enable-PSRemoting یا sconfig گزینهٔ ۴.', 'Reihenfolge: Löst der Name im DNS richtig auf? Test-NetConnection auf Port 5985? Läuft WinRM auf dem Ziel und gibt es einen Listener (winrm enumerate winrm/config/listener)? Ist die Firewall-Regel „Windows-Remoteverwaltung“ für das Profil Domäne aktiv? Wenn nicht: auf dem Ziel Enable-PSRemoting oder sconfig Option 4.', 'Order: does the name resolve correctly in DNS? Test-NetConnection on port 5985? Is WinRM running on the target with a listener (winrm enumerate winrm/config/listener)? Is the “Windows Remote Management” firewall rule enabled for the Domain profile? If not: Enable-PSRemoting or sconfig option 4 on the target.']],
    [['در نشست از راه دور: «دسترسی رد شد» برای \\\\srv02\\freigabe، اما به‌صورت محلی کار می‌کند.', 'In einer Remotesitzung: „Zugriff verweigert“ auf \\\\srv02\\freigabe, lokal geht es.', 'In a remote session: “access denied” to \\\\srv02\\share, locally it works.'],
     ['این همان Double Hop است، نه مشکل مجوز. فرمان را مستقیم روی srv02 با Invoke-Command اجرا کن، یا فایل را از کامپیوتر خودت با Copy-Item -ToSession بفرست. برای حالت‌های دائمی Resource-Based Kerberos Constrained Delegation را با تیم امنیت هماهنگ کن.', 'Das ist das Double-Hop-Problem, kein Rechteproblem. Den Befehl direkt per Invoke-Command auf srv02 ausführen oder die Datei vom eigenen Rechner per Copy-Item -ToSession übertragen. Für Dauerlösungen ressourcenbasierte eingeschränkte Kerberos-Delegierung mit dem Sicherheitsteam abstimmen.', 'That is the double-hop problem, not a permissions problem. Run the command directly on srv02 with Invoke-Command or send the file from your own computer with Copy-Item -ToSession. For permanent needs, agree on resource-based Kerberos constrained delegation with the security team.']],
    [['Server Manager پیام «Online – Performance counters not started» یا «Manageability: cannot retrieve data» نشان می‌دهد.', 'Server Manager zeigt „Online – Leistungsindikatoren nicht gestartet“ oder „Verwaltbarkeit: Daten nicht abrufbar“.', 'Server Manager shows “Online – Performance counters not started” or “Manageability: cannot retrieve data”.'],
     ['برای اولی روی سرور در Server Manager راست‌کلیک و «Start Performance Counters». برای دومی مدیریت از راه دور را روی مقصد فعال کن و قانون‌های فایروال «Remote Event Log Management» و «Windows Remote Management» را روشن کن. همچنین مطمئن شو حساب تو روی آن سرور Admin است.', 'Beim ersten im Server Manager auf den Server rechtsklicken und „Leistungsindikatoren starten“. Beim zweiten auf dem Ziel die Remoteverwaltung aktivieren und die Firewall-Regeln „Remote-Ereignisprotokollverwaltung“ und „Windows-Remoteverwaltung“ einschalten. Außerdem prüfen, dass dein Konto dort Admin ist.', 'For the first, right-click the server in Server Manager and choose “Start Performance Counters”. For the second, enable remote management on the target and turn on the firewall rules “Remote Event Log Management” and “Windows Remote Management”. Also check that your account is admin there.']]
  ],
  decide: [
    [['کدام ابزار برای کدام کار؟', 'Welches Werkzeug wofür?', 'Which tool for which job?'],
     ['PowerShell برای هر کار تکراری یا روی چند سرور (قابل مستندسازی و تکرار). Windows Admin Center برای کار گرافیکی روی یک سرور، به‌ویژه Server Core. Server Manager برای نمای کلی و هشدارها. RDP فقط وقتی برنامه‌ای واقعاً رابط گرافیکی روی خود سرور می‌خواهد.', 'PowerShell für alles Wiederkehrende oder für mehrere Server (dokumentierbar, wiederholbar). Windows Admin Center für grafische Arbeit an einem Server, besonders Server Core. Server Manager für Überblick und Warnungen. RDP nur, wenn eine Anwendung wirklich eine Oberfläche auf dem Server selbst braucht.', 'PowerShell for anything repetitive or for several servers (documentable, repeatable). Windows Admin Center for graphical work on a single server, especially Server Core. Server Manager for overview and alerts. RDP only when an application really needs a GUI on the server itself.']],
    [['Azure Arc لازم است یا نه؟', 'Azure Arc – ja oder nein?', 'Azure Arc – yes or no?'],
     ['بله وقتی می‌خواهی Hotpatch، Azure Update Manager، Defender for Cloud یا سیاست‌های Azure را برای سرورهای محلی داشته باشی. برای یک شرکت کوچک بدون Azure و با ابزار پچ موجود معمولاً لازم نیست؛ هزینهٔ هر سرویس را قبل از فعال‌سازی بررسی کن.', 'Ja, wenn Hotpatch, Azure Update Manager, Defender for Cloud oder Azure-Richtlinien für lokale Server gewünscht sind. Für eine kleine Firma ohne Azure und mit vorhandenem Patchwerkzeug meist nicht nötig; Kosten je Dienst vor dem Aktivieren prüfen.', 'Yes, if you want Hotpatch, Azure Update Manager, Defender for Cloud or Azure policies for on-premises servers. For a small company without Azure and with an existing patch tool usually not needed; check the cost of each service before enabling it.']]
  ],
  iv: [
    [['چطور در پنج دقیقه می‌فهمی روی ۳۰ سرور کدام سرویس خودکار متوقف است؟', 'Wie findest du in fünf Minuten heraus, auf welchem von 30 Servern ein automatischer Dienst gestoppt ist?', 'How do you find out in five minutes which automatic service is stopped on 30 servers?'],
     ['با Invoke-Command روی فهرست سرورها و Get-CimInstance Win32_Service با فیلتر StartMode=Auto و State غیر از Running. نتیجه را با PSComputerName جدول می‌کنم. سرویس‌هایی که عادی متوقف‌اند (Delayed یا Trigger Start) را جدا بررسی می‌کنم.', 'Per Invoke-Command über die Serverliste und Get-CimInstance Win32_Service mit Filter StartMode=Auto und State ungleich Running. Das Ergebnis tabelliere ich mit PSComputerName. Dienste, die normal gestoppt sind (verzögerter oder Trigger-Start), prüfe ich gesondert.', 'With Invoke-Command over the server list and Get-CimInstance Win32_Service filtering StartMode=Auto and State not Running. I tabulate the result with PSComputerName. Services that are normally stopped (delayed or trigger start) I check separately.']]
  ]
},

'ws-files': {
  know: [
    ['در تب Advanced Security پوشه، بخش «Effective Access» نتیجهٔ نهایی مجوز برای یک کاربر یا گروه را نشان می‌دهد؛ قبل از تغییر مجوزها اول همین را ببین.', 'Im Reiter „Erweitert“ der Sicherheitseinstellungen zeigt „Effektiver Zugriff“ das Endergebnis der Rechte für einen Benutzer oder eine Gruppe – vor jeder Rechteänderung zuerst dort nachsehen.', 'In the folder’s Advanced Security dialog, “Effective Access” shows the final permission result for a user or group – check it first before changing permissions.'],
    ['فایل قفل‌شده (مثلاً اکسلی که «در حال استفاده توسط کاربر دیگر» است): با Get-SmbOpenFile روی سرور ببین چه کسی آن را باز کرده و فقط پس از هماهنگی با Close-SmbOpenFile ببند، چون تغییرات ذخیره‌نشدهٔ آن کاربر از بین می‌رود.', 'Gesperrte Datei (etwa eine Excel-Datei „von einem anderen Benutzer verwendet“): Get-SmbOpenFile auf dem Server zeigt, wer sie geöffnet hat; nur nach Absprache per Close-SmbOpenFile schließen, weil ungespeicherte Änderungen dieses Benutzers verloren gehen.', 'Locked file (e.g. an Excel file “in use by another user”): Get-SmbOpenFile on the server shows who has it open; close it with Close-SmbOpenFile only after agreement, because that user’s unsaved changes are lost.'],
    ['FSRM (File Server Resource Manager) برای سهمیهٔ فضا (Quota)، جلوگیری از ذخیرهٔ نوع‌های خاص فایل (File Screen) و گزارش فضای اشغال‌شده است.', 'Der Ressourcen-Manager für Dateiserver (FSRM) bietet Kontingente (Quotas), Dateiprüfungen gegen bestimmte Dateitypen (File Screens) und Speicherberichte.', 'File Server Resource Manager (FSRM) provides quotas, file screens against specific file types and storage reports.']
  ],
  code: R`# Vertiefung: Alltag am Dateiserver (SRV01)
New-Item C:\Temp -ItemType Directory -Force | Out-Null
Get-SmbShare | Format-Table Name,Path,FolderEnumerationMode
Get-SmbShareAccess Buchhaltung
Get-SmbSession | Format-Table ClientComputerName,ClientUserName,NumOpens
Get-SmbOpenFile | Where-Object Path -like '*Buchhaltung*' | Format-Table ClientUserName,ClientComputerName,Path
# gesperrte Datei freigeben – vorher den Benutzer informieren:
# Get-SmbOpenFile | Where-Object Path -like '*Monatsabschluss.xlsx' | Close-SmbOpenFile -Force
icacls C:\Daten\Buchhaltung /save C:\Temp\acl-buchhaltung.txt /t   # Rechte vor Änderungen sichern
vssadmin list shadows /for=C:
Install-WindowsFeature FS-Resource-Manager -IncludeManagementTools
New-FsrmQuota -Path C:\Daten\Buchhaltung -Size 20GB -Description 'Kontingent Buchhaltung'`,
  trouble: [
    [['«دسترسی رد شد» برای یک پوشه، با اینکه کاربر در گروه درست است.', '„Zugriff verweigert“ auf einen Ordner, obwohl der Benutzer in der richtigen Gruppe ist.', '“Access denied” to a folder although the user is in the right group.'],
     ['۱) Effective Access برای همان کاربر. ۲) آیا عضویت تازه است؟ پس Sign out و Sign in. ۳) مجوز Share در برابر NTFS: محدودترین برنده است. ۴) زیرپوشه‌ای با وراثت قطع‌شده یا یک Deny صریح. با icacls مسیر را مقایسه کن و تغییر را در تیکت بنویس.', '1) Effektiver Zugriff für genau diesen Benutzer. 2) Ist die Mitgliedschaft neu? Dann ab- und anmelden. 3) Freigabe- gegen NTFS-Recht: Das restriktivere gewinnt. 4) Unterordner mit unterbrochener Vererbung oder ausdrücklichem Verweigern. Pfad mit icacls vergleichen und die Änderung im Ticket festhalten.', '1) Effective Access for exactly this user. 2) Is the membership new? Then sign out and in. 3) Share vs NTFS permission: the more restrictive wins. 4) A subfolder with broken inheritance or an explicit deny. Compare the path with icacls and record the change in the ticket.']],
    [['«فایل توسط کاربر دیگری در حال استفاده است.»', '„Die Datei wird von einem anderen Benutzer verwendet.“', '“The file is in use by another user.”'],
     ['با Get-SmbOpenFile ببین چه کسی و از کدام کامپیوتر فایل را باز کرده؛ اول با او تماس بگیر تا ذخیره و ببندد. اگر کاربر در دسترس نیست یا نشست قطع شده، با تأیید Close-SmbOpenFile. فایل‌های پنهان ‎~$ کنار فایل‌های Office نشانهٔ قفل باقی‌مانده‌اند.', 'Get-SmbOpenFile zeigt, wer die Datei von welchem Rechner geöffnet hat; zuerst diese Person bitten, zu speichern und zu schließen. Ist sie nicht erreichbar oder die Sitzung verwaist, nach Freigabe Close-SmbOpenFile. Versteckte ~$-Dateien neben Office-Dateien zeigen verwaiste Sperren.', 'Get-SmbOpenFile shows who has the file open from which computer; first ask that person to save and close. If they are unreachable or the session is orphaned, use Close-SmbOpenFile after approval. Hidden ~$ files next to Office files indicate leftover locks.']],
    [['کاربری یک فایل را بازنویسی یا حذف کرده است.', 'Ein Benutzer hat eine Datei überschrieben oder gelöscht.', 'A user overwrote or deleted a file.'],
     ['اگر Shadow Copy فعال است: راست‌کلیک روی پوشه ← Previous Versions؛ نسخه را در مسیر دیگری Restore کن تا فایل فعلی از بین نرود. اگر نسخه نیست، از پشتیبان بازگردان. زمان تقریبی و نام دقیق فایل را از کاربر بپرس.', 'Sind Schattenkopien aktiv: Rechtsklick auf den Ordner → Vorgängerversionen; die Version an einen anderen Ort wiederherstellen, damit die aktuelle Datei nicht verloren geht. Gibt es keine, aus dem Backup wiederherstellen. Ungefähre Uhrzeit und genauen Dateinamen beim Benutzer erfragen.', 'If shadow copies are enabled: right-click the folder → Previous Versions; restore the version to another location so the current file is not lost. If none exists, restore from backup. Ask the user for the approximate time and exact file name.']],
    [['درایو شبکه علامت X قرمز دارد یا بعد از ورود قطع است.', 'Netzlaufwerk zeigt ein rotes X oder ist nach der Anmeldung getrennt.', 'Mapped drive shows a red X or is disconnected after logon.'],
     ['اغلب فقط نمایش است و با کلیک وصل می‌شود؛ اگر نه: Test-NetConnection srv01 -Port 445، ترجمهٔ نام، و اعتبارنامهٔ ذخیره‌شدهٔ قدیمی در Credential Manager. اگر کامپیوتر قبل از شبکه وارد می‌شود (Wi-Fi یا VPN)، GPO «Always wait for the network» را بررسی کن.', 'Oft nur Anzeige, ein Klick verbindet. Sonst: Test-NetConnection srv01 -Port 445, Namensauflösung und alte gespeicherte Anmeldedaten in der Anmeldeinformationsverwaltung prüfen. Meldet sich der Rechner vor dem Netz an (WLAN oder VPN), die GPO „Immer auf das Netzwerk warten“ prüfen.', 'Often only cosmetic and a click reconnects. Otherwise: Test-NetConnection srv01 -Port 445, name resolution and old stored credentials in Credential Manager. If the computer logs on before the network is up (Wi-Fi or VPN), check the GPO “Always wait for the network”.']]
  ],
  decide: [
    [['مجوز را کجا محدود کنم: Share یا NTFS؟', 'Wo einschränken: Freigabe oder NTFS?', 'Where to restrict: share or NTFS?'],
     ['روش رایج: در Share به Authenticated Users مجوز Change (یا Full) بده و همهٔ محدودیت‌های دقیق را در NTFS با گروه‌های DL اعمال کن. این‌طور فقط یک جا را باید بررسی و مستند کرد.', 'Üblich: Auf der Freigabe „Authentifizierte Benutzer“ mit Ändern (oder Vollzugriff) und alle feinen Einschränkungen per NTFS mit DL-Gruppen. So gibt es nur eine Stelle zum Prüfen und Dokumentieren.', 'Common practice: give Authenticated Users Change (or Full) on the share and apply all fine-grained restrictions in NTFS with DL groups. That leaves only one place to check and document.']],
    [['Shadow Copy کافی است یا پشتیبان لازم است؟', 'Reichen Schattenkopien oder braucht es Backup?', 'Are shadow copies enough or is backup needed?'],
     ['Shadow Copy برای بازگرداندن سریع نسخه‌های اخیر توسط خود کاربر خوب است، اما روی همان دیسک است و با خرابی دیسک یا باج‌افزار از بین می‌رود. پشتیبان جداگانه (3-2-1) همیشه لازم است.', 'Schattenkopien sind gut für schnelle Selbsthilfe bei aktuellen Versionen, liegen aber auf derselben Platte und gehen bei Plattenausfall oder Ransomware verloren. Ein getrenntes Backup (3-2-1) ist immer nötig.', 'Shadow copies are good for quick self-service restores of recent versions, but they live on the same disk and are lost with disk failure or ransomware. A separate backup (3-2-1) is always required.']]
  ],
  iv: [
    [['مدیر بخش می‌خواهد بداند چه کسانی به پوشهٔ «Personal» دسترسی دارند. چطور جواب می‌دهی؟', 'Eine Abteilungsleitung will wissen, wer Zugriff auf den Ordner „Personal“ hat. Wie antwortest du?', 'A department head wants to know who has access to the “HR” folder. How do you answer?'],
     ['با icacls یا Get-Acl گروه‌های روی پوشه را درمی‌آورم، اعضای هر گروه را با Get-ADGroupMember -Recursive فهرست می‌کنم و مجوز Share را هم ضمیمه می‌کنم. برای کاربر خاص Effective Access. گزارش را با تاریخ در تیکت ذخیره می‌کنم.', 'Mit icacls oder Get-Acl die Gruppen am Ordner auslesen, deren Mitglieder per Get-ADGroupMember -Recursive auflisten und die Freigaberechte dazulegen. Für einzelne Personen Effektiver Zugriff. Den Bericht mit Datum im Ticket ablegen.', 'Read the groups on the folder with icacls or Get-Acl, list their members with Get-ADGroupMember -Recursive and add the share permissions. For individuals use Effective Access. Store the dated report in the ticket.']]
  ]
},

'ws-pki': {
  know: [
    ['certutil -verify -urlfetch روی یک فایل گواهی زنجیره، دسترسی به CRL و AIA و دلیل نامعتبر بودن را دقیق نشان می‌دهد؛ بهترین ابزار عیب‌یابی PKI است.', 'certutil -verify -urlfetch auf eine Zertifikatsdatei zeigt Kette, Erreichbarkeit von CRL und AIA und den genauen Grund, warum ein Zertifikat ungültig ist – das wichtigste PKI-Diagnosewerkzeug.', 'certutil -verify -urlfetch on a certificate file shows the chain, reachability of CRL and AIA and the exact reason a certificate is invalid – the most important PKI diagnostic tool.'],
    ['گواهی‌هایی که تا ۳۰ روز دیگر منقضی می‌شوند را مرتب پیدا کن (مثلاً با PowerShell در یک Task زمان‌بندی‌شده). گواهی منقضی‌شده یکی از رایج‌ترین علت‌های قطعی ناگهانی وب‌سایت، VPN و Wi-Fi است.', 'Zertifikate, die in den nächsten 30 Tagen ablaufen, regelmäßig suchen (etwa per PowerShell in einer geplanten Aufgabe). Abgelaufene Zertifikate gehören zu den häufigsten Ursachen plötzlicher Ausfälle bei Website, VPN und WLAN.', 'Regularly look for certificates expiring within 30 days (e.g. with PowerShell in a scheduled task). Expired certificates are among the most common causes of sudden website, VPN and Wi-Fi outages.'],
    ['عمر گواهی‌های عمومی TLS کوتاه می‌شود: طبق تصمیم CA/Browser Forum از مارس ۲۰۲۶ حداکثر ۲۰۰ روز و در سال‌های بعد کمتر. پس تمدید خودکار (مثلاً ACME) مهم‌تر از همیشه است.', 'Öffentliche TLS-Zertifikate werden kürzer: Nach Beschluss des CA/Browser Forums seit März 2026 höchstens 200 Tage, in den Folgejahren weniger. Automatische Erneuerung (etwa ACME) wird damit Pflicht.', 'Public TLS certificates are getting shorter: per the CA/Browser Forum decision, at most 200 days since March 2026 and less in later years. Automatic renewal (e.g. ACME) becomes essential.']
  ],
  code: R`# Vertiefung: Zertifikate prüfen und überwachen
New-Item C:\Temp -ItemType Directory -Force | Out-Null
Get-ChildItem Cert:\LocalMachine\My | Format-Table Subject,NotAfter,Thumbprint
Get-ChildItem Cert:\LocalMachine\My | Where-Object NotAfter -lt (Get-Date).AddDays(30) | Format-Table Subject,NotAfter
$c = Get-ChildItem Cert:\LocalMachine\My | Sort-Object NotAfter -Descending | Select-Object -First 1
$c.DnsNameList                               # SAN-Namen
Export-Certificate -Cert $c -FilePath C:\Temp\srv01.cer
certutil -verify -urlfetch C:\Temp\srv01.cer
# auf der CA: neue Sperrliste veröffentlichen
certutil -CRL
# auf dem Client: automatische Registrierung sofort auslösen
certutil -pulse`,
  trouble: [
    [['مرورگر خطای NET::ERR_CERT_COMMON_NAME_INVALID می‌دهد.', 'Browser meldet NET::ERR_CERT_COMMON_NAME_INVALID.', 'Browser reports NET::ERR_CERT_COMMON_NAME_INVALID.'],
     ['نامی که کاربر وارد کرده (مثلاً intranet یا intranet.corp.example.test) در SAN گواهی نیست. مرورگرهای امروزی فقط SAN را بررسی می‌کنند، نه CN. گواهی تازه با همهٔ نام‌های لازم در SAN بگیر و در Binding وب‌سرور جایگزین کن.', 'Der eingegebene Name (etwa intranet oder intranet.corp.example.test) steht nicht im SAN des Zertifikats. Aktuelle Browser prüfen nur den SAN, nicht den CN. Neues Zertifikat mit allen nötigen Namen im SAN ausstellen und in der Bindung des Webservers tauschen.', 'The name the user typed (e.g. intranet or intranet.corp.example.test) is not in the certificate’s SAN. Current browsers only check the SAN, not the CN. Issue a new certificate with all required names in the SAN and replace it in the web server binding.']],
    [['«وضعیت ابطال گواهی بررسی نشد» – ناگهان برای VPN، Wi-Fi یا وب‌سایت‌ها.', '„Die Sperrung des Zertifikats konnte nicht geprüft werden“ – plötzlich bei VPN, WLAN oder Websites.', '“The revocation status of the certificate could not be checked” – suddenly for VPN, Wi-Fi or websites.'],
     ['CRL منقضی شده یا مسیر CDP در دسترس نیست. با certutil -verify -urlfetch ببین کدام CRL شکست می‌خورد. شایع‌ترین علت: CRL مربوط به Root CA آفلاین که مرتب تمدید نشده است. CA ریشه را روشن کن، certutil -CRL بزن و فایل را در محل CDP کپی کن؛ این کار را در تقویم ثبت کن.', 'Die Sperrliste ist abgelaufen oder der CDP-Pfad nicht erreichbar. certutil -verify -urlfetch zeigt, welche CRL scheitert. Häufigste Ursache: die CRL der Offline-Stamm-CA wurde nicht rechtzeitig erneuert. Stamm-CA starten, certutil -CRL ausführen und die Datei an den CDP-Ort kopieren – und als Termin im Kalender eintragen.', 'The CRL has expired or the CDP path is unreachable. certutil -verify -urlfetch shows which CRL fails. Most common cause: the offline root CA’s CRL was not renewed in time. Start the root CA, run certutil -CRL and copy the file to the CDP location – and put it in the calendar.']],
    [['گواهی CA داخلی روی برخی دستگاه‌ها نامعتبر است.', 'Zertifikat der internen CA gilt auf manchen Geräten als nicht vertrauenswürdig.', 'Internal CA certificate is untrusted on some devices.'],
     ['کامپیوترهای عضو دامنه Root CA سازمانی را خودکار از AD می‌گیرند؛ گوشی‌ها، دستگاه‌های خارج از دامنه، لینوکس و Java نه. گواهی Root را با Intune، GPO یا دستی در محل مطمئن آن سیستم (Trusted Root) نصب کن. اگر CA میانی هم هست، زنجیره کامل باشد.', 'Domänencomputer erhalten die Unternehmens-Stamm-CA automatisch aus AD; Handys, Nicht-Domänengeräte, Linux und Java nicht. Das Stammzertifikat per Intune, GPO oder von Hand in den vertrauenswürdigen Speicher des jeweiligen Systems bringen. Bei Zwischen-CA die vollständige Kette ausliefern.', 'Domain computers get the enterprise root CA automatically from AD; phones, non-domain devices, Linux and Java do not. Deploy the root certificate via Intune, GPO or manually into that system’s trusted root store. With an intermediate CA, deliver the full chain.']],
    [['ثبت خودکار گواهی (Autoenrollment) انجام نمی‌شود.', 'Automatische Zertifikatsregistrierung passiert nicht.', 'Certificate autoenrollment does not happen.'],
     ['سه شرط: در قالب گواهی گروه مربوط مجوز Read، Enroll و Autoenroll دارد؛ قالب روی CA منتشر شده است (Certificate Templates to Issue)؛ GPO مربوط به Autoenrollment فعال است. سپس روی کلاینت gpupdate و certutil -pulse و لاگ Application را ببین.', 'Drei Bedingungen: In der Vorlage hat die Gruppe Lesen, Registrieren und Automatisch registrieren; die Vorlage ist auf der CA veröffentlicht (Auszustellende Zertifikatvorlagen); die GPO für automatische Registrierung ist aktiv. Dann auf dem Client gpupdate, certutil -pulse und das Anwendungsprotokoll prüfen.', 'Three conditions: in the template the group has Read, Enroll and Autoenroll; the template is published on the CA (Certificate Templates to Issue); the autoenrollment GPO is enabled. Then run gpupdate and certutil -pulse on the client and check the Application log.']]
  ],
  decide: [
    [['گواهی CA داخلی یا گواهی عمومی؟', 'Interne CA oder öffentliches Zertifikat?', 'Internal CA or public certificate?'],
     ['گواهی عمومی برای هر نامی که از اینترنت یا با دستگاه‌های بیرونی باز می‌شود (وب‌سایت، Webmail، پورتال VPN). CA داخلی برای نام‌های داخلی، 802.1X، احراز هویت دستگاه‌ها و سرورهای درون شبکه.', 'Öffentliches Zertifikat für jeden Namen, der aus dem Internet oder von fremden Geräten aufgerufen wird (Website, Webmail, VPN-Portal). Interne CA für interne Namen, 802.1X, Geräteauthentifizierung und Server im eigenen Netz.', 'Public certificate for any name accessed from the internet or by external devices (website, webmail, VPN portal). Internal CA for internal names, 802.1X, device authentication and servers inside the network.']],
    [['CA یک‌سطحی یا دوسطحی؟', 'Einstufige oder zweistufige CA?', 'One-tier or two-tier CA?'],
     ['در شرکت واقعی دوسطحی: Root آفلاین و CA صادرکننده روی شبکه، تا کلید Root امن بماند. یک‌سطحی فقط برای آزمایشگاه یا محیط خیلی کوچک قابل قبول است؛ تغییر آن بعداً سخت است.', 'Im echten Unternehmen zweistufig: Offline-Stamm-CA und Online-Ausstellungs-CA, damit der Stammschlüssel sicher bleibt. Einstufig nur im Labor oder sehr kleinen Umgebungen vertretbar – ein späterer Umbau ist aufwendig.', 'In a real company two-tier: offline root and online issuing CA, so the root key stays safe. One-tier is acceptable only in a lab or very small environment – changing it later is costly.']]
  ],
  iv: [
    [['وب‌سایت داخلی ناگهان خطای گواهی می‌دهد. چه چیزهایی را بررسی می‌کنی؟', 'Die interne Website zeigt plötzlich einen Zertifikatsfehler. Was prüfst du?', 'The internal website suddenly shows a certificate error. What do you check?'],
     ['پیام دقیق خطا، تاریخ انقضا، نام در SAN، زنجیره و CRL با certutil -verify -urlfetch، و اینکه کلاینت Root را دارد یا نه. معمولاً یا گواهی منقضی شده یا CRL. بعد از رفع، یادآور انقضا یا تمدید خودکار تنظیم می‌کنم.', 'Genaue Fehlermeldung, Ablaufdatum, Name im SAN, Kette und CRL per certutil -verify -urlfetch und ob der Client die Stamm-CA hat. Meist ist das Zertifikat oder die CRL abgelaufen. Danach richte ich eine Ablaufwarnung oder automatische Erneuerung ein.', 'Exact error message, expiry date, name in the SAN, chain and CRL with certutil -verify -urlfetch, and whether the client has the root. Usually the certificate or the CRL has expired. Afterwards I set up an expiry alert or automatic renewal.']]
  ]
},

'ws-hyperv': {
  know: [
    ['هر Checkpoint یک فایل AVHDX می‌سازد که تا حذف Checkpoint بزرگ می‌شود. فایل‌های AVHDX را هرگز دستی پاک نکن؛ Checkpoint را در Hyper-V Manager حذف کن تا Merge انجام شود.', 'Jeder Prüfpunkt erzeugt eine AVHDX-Datei, die bis zum Löschen des Prüfpunkts wächst. AVHDX-Dateien nie von Hand löschen – den Prüfpunkt im Hyper-V-Manager entfernen, damit zusammengeführt wird.', 'Each checkpoint creates an AVHDX file that grows until the checkpoint is deleted. Never delete AVHDX files manually – delete the checkpoint in Hyper-V Manager so it is merged.'],
    ['Hyper-V Replica یک نسخه از VM را با تأخیر چنددقیقه‌ای روی میزبان دوم نگه می‌دارد؛ برای بازیابی در حادثه (DR) مفید است ولی جایگزین پشتیبان نیست.', 'Hyper-V-Replikat hält eine Kopie der VM mit wenigen Minuten Verzögerung auf einem zweiten Host – nützlich für die Notfallwiederherstellung, aber kein Ersatz für Backup.', 'Hyper-V Replica keeps a copy of the VM on a second host with a delay of a few minutes – useful for disaster recovery but no replacement for backup.'],
    ['فضای خالی دیسک میزبان را پایش کن: اگر دیسک VMها پر شود، Hyper-V ماشین‌ها را در حالت «Paused-Critical» متوقف می‌کند.', 'Freien Speicher des Hosts überwachen: Läuft das Laufwerk mit den VMs voll, hält Hyper-V die Maschinen im Zustand „Angehalten – kritisch“ an.', 'Monitor free space on the host: if the VM volume fills up, Hyper-V stops machines in the “Paused-Critical” state.']
  ],
  code: R`# Vertiefung: Hyper-V-Betrieb und Fehlersuche (auf dem Host)
Get-VM | Format-Table Name,State,CPUUsage,MemoryAssigned,Uptime,Status
Get-VMSnapshot -VMName * | Format-Table VMName,Name,CreationTime
Get-VM | Get-VMHardDiskDrive | Format-Table VMName,Path
Get-VMSwitch | Format-Table Name,SwitchType,NetAdapterInterfaceDescription
Get-VMNetworkAdapterVlan -VMName * | Format-Table VMName,OperationMode,AccessVlanId
Get-VMIntegrationService -VMName SRV01 | Format-Table Name,Enabled,PrimaryStatusDescription
Get-WinEvent -LogName 'Microsoft-Windows-Hyper-V-VMMS-Admin' -MaxEvents 20 |
  Where-Object Level -le 3 | Format-Table TimeCreated,Id,Message -Wrap
Get-PSDrive -PSProvider FileSystem           # Platz für VHDX und AVHDX`,
  trouble: [
    [['یک VM در حالت «Paused-Critical» است.', 'Eine VM steht auf „Angehalten – kritisch“ (Paused-Critical).', 'A VM is in “Paused-Critical” state.'],
     ['تقریباً همیشه دیسک میزبان پر شده است، اغلب به خاطر AVHDX یک Checkpoint قدیمی. فضا آزاد کن (فایل‌های غیرضروری، انتقال یک VM)، سپس VM را Resume کن. Checkpointهای قدیمی را از کنسول حذف کن و صبر کن Merge تمام شود.', 'Fast immer ist das Host-Laufwerk voll, oft durch die AVHDX eines alten Prüfpunkts. Platz schaffen (unnötige Dateien, eine VM verschieben), dann die VM fortsetzen. Alte Prüfpunkte in der Konsole löschen und warten, bis das Zusammenführen fertig ist.', 'Almost always the host volume is full, often due to an old checkpoint’s AVHDX. Free up space (unneeded files, move a VM), then resume the VM. Delete old checkpoints in the console and wait for the merge to finish.']],
    [['VM اجرا نمی‌شود: «حافظهٔ کافی نیست».', 'VM startet nicht: „nicht genügend Arbeitsspeicher“.', 'VM does not start: “not enough memory”.'],
     ['حافظهٔ آزاد میزبان را با Get-VM و Task Manager ببین. Startup Memory همان VM را پایین بیاور یا Dynamic Memory را فعال کن، یا VM کم‌اهمیتی را خاموش کن. برای میزبان همیشه چند گیگابایت برای خود سیستم‌عامل آزاد نگه دار.', 'Freien Host-Speicher per Get-VM und Task-Manager prüfen. Startspeicher dieser VM senken oder dynamischen Arbeitsspeicher aktivieren oder eine unwichtige VM herunterfahren. Für den Host immer einige GB für das eigene Betriebssystem frei lassen.', 'Check free host memory with Get-VM and Task Manager. Lower this VM’s startup memory or enable dynamic memory, or shut down a less important VM. Always keep a few GB free for the host OS itself.']],
    [['یک VM شبکه ندارد، بقیه دارند.', 'VM hat kein Netzwerk, andere VMs schon.', 'One VM has no network, others do.'],
     ['کارت شبکهٔ VM به کدام vSwitch وصل است؟ VLAN ID روی کارت مجازی با VLAN شبکه یکی است (Get-VMNetworkAdapterVlan)؟ داخل VM کارت شبکه شناخته شده و IP درست دارد؟ اگر بعد از جابه‌جایی VM است، نام vSwitch روی میزبان جدید باید دقیقاً همان باشد.', 'An welchem virtuellen Switch hängt die Netzwerkkarte der VM? Stimmt die VLAN-ID der virtuellen Karte mit dem Netz überein (Get-VMNetworkAdapterVlan)? Wird die Karte in der VM erkannt und hat sie die richtige IP? Nach einer Migration muss der Switchname auf dem neuen Host exakt gleich sein.', 'Which virtual switch is the VM’s NIC connected to? Does the VLAN ID on the virtual NIC match the network (Get-VMNetworkAdapterVlan)? Is the NIC detected inside the VM with the correct IP? After a migration the switch name on the new host must be exactly the same.']]
  ],
  decide: [
    [['Checkpoint یا پشتیبان؟', 'Prüfpunkt oder Backup?', 'Checkpoint or backup?'],
     ['Checkpoint فقط درست قبل از یک تغییر کوتاه (به‌روزرسانی، نصب) و حذف آن در همان روز. پشتیبان برای حفاظت واقعی، روی سیستم جدا. روی DC و پایگاه داده‌ها فقط Production Checkpoint.', 'Prüfpunkt nur direkt vor einer kurzen Änderung (Update, Installation) und noch am selben Tag löschen. Backup für echten Schutz, auf einem getrennten System. Auf DCs und Datenbanken nur Produktionsprüfpunkte.', 'Checkpoint only right before a short change (update, installation) and delete it the same day. Backup for real protection on a separate system. On DCs and databases only production checkpoints.']],
    [['کدام نوع vSwitch؟', 'Welcher virtuelle Switch?', 'Which virtual switch?'],
     ['External برای VMهایی که با شبکهٔ واقعی کار می‌کنند (سرورها). Internal برای ارتباط میزبان و VMها در آزمایشگاه. Private برای آزمایشگاه کاملاً جدا، مثلاً تمرین با بدافزار یا شبیه‌سازی خرابی.', 'Extern für VMs, die mit dem echten Netz arbeiten (Server). Intern für Verbindung zwischen Host und VMs im Labor. Privat für ein völlig getrenntes Labor, etwa für Schadsoftwaretests oder Ausfallsimulationen.', 'External for VMs that work with the real network (servers). Internal for host-to-VM communication in a lab. Private for a fully isolated lab, e.g. malware tests or failure simulations.']]
  ],
  iv: [
    [['همکاری Checkpointی را که سه ماه پیش ساخته شده پیدا کرده. چه کار می‌کنی؟', 'Ein Kollege findet einen drei Monate alten Prüfpunkt. Was tust du?', 'A colleague finds a three-month-old checkpoint. What do you do?'],
     ['اول مطمئن می‌شوم پشتیبان سالم از VM هست و فضای کافی برای Merge روی دیسک وجود دارد. بعد Checkpoint را از Hyper-V Manager در زمان کم‌بار حذف می‌کنم و پیشرفت Merge را تا پایان دنبال می‌کنم. AVHDX را دستی پاک نمی‌کنم.', 'Zuerst prüfe ich, dass ein gültiges Backup der VM existiert und genug Platz für das Zusammenführen da ist. Dann lösche ich den Prüfpunkt im Hyper-V-Manager in einer ruhigen Zeit und verfolge das Zusammenführen bis zum Ende. Die AVHDX lösche ich nie von Hand.', 'First I make sure a valid backup of the VM exists and there is enough space for the merge. Then I delete the checkpoint in Hyper-V Manager during a quiet period and follow the merge to the end. I never delete the AVHDX manually.']]
  ]
},

'ws-iis': {
  know: [
    ['کد وضعیت فرعی (Substatus) در لاگ IIS علت را دقیق‌تر می‌گوید: 401.1 ورود ناموفق، 403.14 صفحهٔ پیش‌فرض نیست و فهرست پوشه ممنوع است، 404.0 فایل نیست، 500.19 فایل web.config نامعتبر است یا ماژول نصب نیست، 503 Application Pool متوقف است.', 'Der Unterstatus im IIS-Log nennt die Ursache genauer: 401.1 Anmeldung fehlgeschlagen, 403.14 kein Standarddokument und Verzeichnisliste verboten, 404.0 Datei fehlt, 500.19 web.config ungültig oder Modul fehlt, 503 Anwendungspool gestoppt.', 'The substatus in the IIS log gives the exact cause: 401.1 logon failed, 403.14 no default document and directory listing denied, 404.0 file missing, 500.19 invalid web.config or missing module, 503 application pool stopped.'],
    ['Rapid-Fail Protection: اگر Pool در مدت کوتاه چند بار Crash کند، IIS آن را متوقف می‌کند و سایت 503 می‌دهد. علت را در لاگ System (منبع WAS) و لاگ Application ببین، نه فقط Pool را دوباره روشن کن.', 'Rapid-Fail Protection: Stürzt ein Pool mehrmals kurz hintereinander ab, stoppt IIS ihn und die Site liefert 503. Ursache im Systemprotokoll (Quelle WAS) und Anwendungsprotokoll suchen, nicht nur den Pool neu starten.', 'Rapid-fail protection: if a pool crashes several times in a short period, IIS stops it and the site returns 503. Find the cause in the System log (source WAS) and the Application log instead of just restarting the pool.'],
    ['هویت Application Pool (مثلاً IIS AppPool\\Intranet) باید روی پوشهٔ سایت مجوز خواندن داشته باشد؛ بسیاری از خطاهای 401 و 500 به همین برمی‌گردد.', 'Die Identität des Anwendungspools (etwa IIS AppPool\\Intranet) braucht Leserecht auf den Site-Ordner – viele 401- und 500-Fehler gehen darauf zurück.', 'The application pool identity (e.g. IIS AppPool\\Intranet) needs read permission on the site folder – many 401 and 500 errors trace back to this.']
  ],
  code: R`# Vertiefung: IIS-Fehlersuche (SRV01)
Import-Module WebAdministration
Get-IISSite
Get-ChildItem IIS:\AppPools | Format-Table Name,State,ManagedRuntimeVersion
Get-WebAppPoolState -Name DefaultAppPool
Start-WebAppPool -Name DefaultAppPool
Get-WebBinding | Format-Table protocol,bindingInformation,sslFlags
netsh http show sslcert
# letzte Zeilen des aktuellen Logs (Spalten sc-status und sc-substatus beachten):
Get-ChildItem C:\inetpub\logs\LogFiles\W3SVC1 | Sort-Object LastWriteTime | Select-Object -Last 1 | Get-Content -Tail 20
Get-WinEvent -LogName System -MaxEvents 100 | Where-Object ProviderName -eq 'WAS' | Format-Table TimeCreated,Id,Message -Wrap
icacls C:\inetpub\wwwroot`,
  trouble: [
    [['وب‌سایت خطای 503 Service Unavailable می‌دهد.', 'Website liefert 503 Service Unavailable.', 'Website returns 503 Service Unavailable.'],
     ['Application Pool متوقف است. لاگ System (منبع WAS) دلیل را می‌گوید: Crash مکرر برنامه (Rapid-Fail Protection) یا رمز حساب هویت Pool که عوض شده. علت را رفع کن (رمز در Advanced Settings، خطای برنامه در لاگ Application)، بعد Start-WebAppPool.', 'Der Anwendungspool ist gestoppt. Das Systemprotokoll (Quelle WAS) nennt den Grund: wiederholte Abstürze (Rapid-Fail Protection) oder ein geändertes Kennwort der Pool-Identität. Ursache beheben (Kennwort in den erweiterten Einstellungen, Anwendungsfehler im Anwendungsprotokoll), dann Start-WebAppPool.', 'The application pool is stopped. The System log (source WAS) gives the reason: repeated crashes (rapid-fail protection) or a changed password of the pool identity. Fix the cause (password in Advanced Settings, application error in the Application log), then Start-WebAppPool.']],
    [['خطای 500.19 بعد از کپی کردن یک برنامهٔ جدید.', 'Fehler 500.19 nach dem Kopieren einer neuen Anwendung.', 'Error 500.19 after copying a new application.'],
     ['web.config بخشی دارد که IIS نمی‌شناسد، معمولاً چون ماژولی مثل URL Rewrite یا ASP.NET Core Hosting Bundle نصب نیست، یا IIS_IUSRS به پوشه دسترسی ندارد. صفحهٔ خطای دقیق (روی خود سرور) خط مشکل‌دار را نشان می‌دهد.', 'Die web.config enthält einen Abschnitt, den IIS nicht kennt – meist fehlt ein Modul wie URL Rewrite oder das ASP.NET Core Hosting Bundle – oder IIS_IUSRS hat keinen Zugriff auf den Ordner. Die ausführliche Fehlerseite (lokal auf dem Server) zeigt die fehlerhafte Zeile.', 'web.config contains a section IIS does not know – usually a module such as URL Rewrite or the ASP.NET Core Hosting Bundle is missing – or IIS_IUSRS has no access to the folder. The detailed error page (locally on the server) shows the faulty line.']],
    [['خطای 401 یا 403 برای برخی کاربران یا همه.', '401 oder 403 für einzelne Benutzer oder alle.', '401 or 403 for some or all users.'],
     ['روش‌های احراز هویت سایت را ببین (Anonymous یا Windows). برای Windows Authentication مرورگر باید سایت را در Intranet Zone بداند تا خودکار وارد شود. مجوز NTFS برای هویت Pool و گروه کاربران را بررسی کن. 403.14 یعنی فایل پیش‌فرض (index.html) نیست.', 'Authentifizierungsmethoden der Site prüfen (anonym oder Windows). Für Windows-Authentifizierung muss der Browser die Site in der Intranetzone sehen, um automatisch anzumelden. NTFS-Rechte für Pool-Identität und Benutzergruppe prüfen. 403.14 heißt: kein Standarddokument (index.html).', 'Check the site’s authentication methods (anonymous or Windows). For Windows authentication the browser must treat the site as Intranet zone to log on automatically. Check NTFS permissions for the pool identity and user group. 403.14 means no default document (index.html).']],
    [['HTTPS گواهی اشتباه یا وب‌سایت دیگری را نشان می‌دهد.', 'HTTPS zeigt das falsche Zertifikat oder eine andere Website.', 'HTTPS shows the wrong certificate or another website.'],
     ['چند سایت روی یک IP و پورت 443 به SNI نیاز دارند: در Binding هر سایت Host Name را بنویس و «Require Server Name Indication» را فعال کن. با netsh http show sslcert ببین کدام گواهی به کدام نام و پورت وصل است.', 'Mehrere Sites auf einer IP und Port 443 brauchen SNI: In jeder Bindung den Hostnamen eintragen und „Servernamensanzeige erforderlich“ aktivieren. netsh http show sslcert zeigt, welches Zertifikat an welchen Namen und Port gebunden ist.', 'Several sites on one IP and port 443 need SNI: enter the host name in each binding and enable “Require Server Name Indication”. netsh http show sslcert shows which certificate is bound to which name and port.']]
  ],
  decide: [
    [['یک Application Pool برای همه یا جدا برای هر برنامه؟', 'Ein Anwendungspool für alle oder je Anwendung einer?', 'One application pool for all or one per application?'],
     ['برای هر برنامه یک Pool جدا: Crash یا Recycle یک برنامه روی بقیه اثر نمی‌گذارد و مجوزها با هویت جداگانه دقیق‌تر می‌شوند.', 'Je Anwendung ein eigener Pool: Absturz oder Recycling einer Anwendung trifft die anderen nicht, und Rechte lassen sich über getrennte Identitäten genau vergeben.', 'One pool per application: a crash or recycle of one application does not affect others, and permissions can be set precisely via separate identities.']],
    [['IIS مستقیم در اینترنت یا پشت Reverse Proxy؟', 'IIS direkt im Internet oder hinter Reverse Proxy?', 'IIS directly on the internet or behind a reverse proxy?'],
     ['برنامه‌های داخلی فقط در شبکهٔ داخلی. اگر باید از بیرون در دسترس باشد: پشت Reverse Proxy یا WAF در DMZ، با گواهی عمومی و به‌روزرسانی منظم؛ هرگز IIS داخلی را مستقیم با Port Forwarding در اینترنت قرار نده.', 'Interne Anwendungen nur im internen Netz. Muss etwas von außen erreichbar sein: hinter Reverse Proxy oder WAF in der DMZ, mit öffentlichem Zertifikat und regelmäßigen Updates – nie einen internen IIS per Portweiterleitung direkt ins Internet stellen.', 'Internal applications only on the internal network. If something must be reachable from outside: behind a reverse proxy or WAF in the DMZ, with a public certificate and regular updates – never expose an internal IIS directly via port forwarding.']]
  ],
  iv: [
    [['کاربران خطای 503 می‌بینند. اولین کارهایت چیست؟', 'Benutzer sehen 503. Was sind deine ersten Schritte?', 'Users see 503. What are your first steps?'],
     ['وضعیت Application Pool را بررسی می‌کنم؛ اگر متوقف است، دلیلش را در لاگ System (WAS) و Application می‌خوانم، علت را رفع می‌کنم و Pool را روشن می‌کنم. بعد سایت را با کاربر آزمایش و علت را در تیکت ثبت می‌کنم تا تکرار نشود.', 'Ich prüfe den Zustand des Anwendungspools; ist er gestoppt, lese ich den Grund im System- (WAS) und Anwendungsprotokoll, behebe die Ursache und starte den Pool. Dann teste ich mit dem Benutzer und dokumentiere die Ursache im Ticket, damit es nicht wieder passiert.', 'I check the application pool state; if it is stopped, I read the reason in the System (WAS) and Application logs, fix the cause and start the pool. Then I test with the user and document the cause in the ticket so it does not recur.']]
  ]
}

});
})();
